class Solution {
    public int bestProfit(int[] prices) {
        int minSoFar = prices[0];
        int best = 0;
        for (int p : prices) {
            best = Math.max(best, p - minSoFar);
            minSoFar = Math.min(minSoFar, p);
        }
        return best;
    }
}

